"""Durable, tenant-scoped export jobs with leased, replayable writes."""

import copy
import hashlib
import json

from .store import JsonStore, identifier, integer
from .validation import rows_value, live


class ExportQueue:
    def __init__(self, path):
        self.store = JsonStore(path)

    @staticmethod
    def _job(data, tenant, job_id):
        identifier(tenant)
        identifier(job_id)
        try:
            return data['tenants'][tenant]['jobs'][job_id]
        except KeyError:
            raise ValueError('unknown job') from None

    def submit(self, tenant, job_id, rows):
        identifier(tenant)
        identifier(job_id)
        rows_value(rows)
        rows = copy.deepcopy(rows)

        def action(data):
            tenant_state = data.setdefault('tenants', {}).setdefault(tenant, {'jobs': {}})
            jobs = tenant_state['jobs']
            if job_id in jobs:
                if jobs[job_id]['rows'] != rows:
                    raise ValueError('submit conflict')
                return False
            if len(jobs) >= 1000:
                raise ValueError('too many jobs')
            jobs[job_id] = dict(
                rows=rows, state='queued', cursor=0, chunks={},
                lease=None, artifact_sha256=None, commit=None,
            )
            return True

        return self.store.transact(action)

    def claim(self, tenant, worker, now, ttl):
        identifier(tenant)
        identifier(worker)
        integer(now)
        integer(ttl, 1, 1_000_000)

        def action(data):
            # The counter is global to this store, not a tenant or a job. Even
            # an empty claim advances it; a failed transaction never does.
            data['next_token'] = data.get('next_token', 0) + 1
            jobs = data.get('tenants', {}).get(tenant, {}).get('jobs', {})
            eligible = [
                job_id for job_id, job in jobs.items()
                if job['state'] == 'queued'
                or (job['state'] == 'running' and job['lease']['expires'] <= now)
            ]
            if not eligible:
                return None
            job_id = min(eligible)
            job = jobs[job_id]
            token = 'claim-' + str(data['next_token'])
            job['state'] = 'running'
            job['lease'] = dict(token=token, worker=worker, expires=now + ttl)
            return dict(job_id=job_id, token=token, cursor=job['cursor'])

        return self.store.transact(action)

    def append(self, tenant, job_id, token, chunk_id, rows, now):
        identifier(tenant)
        identifier(job_id)
        identifier(token)
        identifier(chunk_id)
        integer(now)
        rows_value(rows, nonempty=True)
        rows = copy.deepcopy(rows)

        def action(data):
            job = self._job(data, tenant, job_id)
            # Replays still need the *current* live lease. Chunk receipts belong
            # to the job, however, and survive lease changes.
            live(job, token, now)
            if chunk_id in job['chunks']:
                if job['chunks'][chunk_id] != rows:
                    raise ValueError('chunk conflict')
                return False
            cursor = job['cursor']
            if job['rows'][cursor:cursor + len(rows)] != rows:
                raise ValueError('noncontiguous chunk')
            job['chunks'][chunk_id] = rows
            job['cursor'] += len(rows)
            return True

        return self.store.transact(action)

    def commit(self, tenant, job_id, token, commit_id, now):
        identifier(tenant)
        identifier(job_id)
        identifier(token)
        identifier(commit_id)
        integer(now)

        def action(data):
            job = self._job(data, tenant, job_id)
            if job['state'] == 'completed':
                if job['commit'] != dict(token=token, id=commit_id):
                    raise ValueError('commit conflict')
                return job['artifact_sha256']
            live(job, token, now)
            if job['cursor'] != len(job['rows']):
                raise ValueError('partial export')
            digest = hashlib.sha256(json.dumps(
                job['rows'], sort_keys=True, separators=(',', ':'),
                ensure_ascii=False,
            ).encode('utf-8')).hexdigest()
            job.update(
                state='completed', lease=None, artifact_sha256=digest,
                commit=dict(token=token, id=commit_id),
            )
            return digest

        return self.store.transact(action)

    def cancel(self, tenant, job_id, request_id):
        """Cancel an uncommitted job, retaining its submission and chunk history."""
        identifier(tenant)
        identifier(job_id)
        identifier(request_id)

        def action(data):
            job = self._job(data, tenant, job_id)
            tenant_state = data['tenants'][tenant]
            # Older stores need no migration: add the tenant receipt map only
            # when a cancellation succeeds, never when opening the store.
            receipts = tenant_state.get('cancellations', {})
            if request_id in receipts:
                if receipts[request_id] != job_id:
                    raise ValueError('cancellation request conflict')
                return False
            if job['state'] == 'completed':
                raise ValueError('completed job cannot be cancelled')

            # A fresh receipt is durable even if the job was already cancelled.
            tenant_state.setdefault('cancellations', {})[request_id] = job_id
            if job['state'] == 'cancelled':
                return False
            job.update(state='cancelled', lease=None, artifact_sha256=None)
            return True

        return self.store.transact(action)

    def inspect(self, tenant, job_id):
        job = self._job(self.store.data, tenant, job_id)
        # All fields are immutable scalars in a newly allocated result dict.
        return dict(
            state=job['state'], cursor=job['cursor'], total=len(job['rows']),
            artifact_sha256=job['artifact_sha256'],
            lease_expires=job['lease']['expires'] if job['lease'] else None,
        )

