"""Copy-on-write JSON persistence for a single queue writer."""

import copy
import json
import os
from pathlib import Path
import tempfile


class JsonStore:
    def __init__(self, path):
        self.path = Path(path)
        self.data = (
            json.loads(self.path.read_text(encoding='utf-8'))
            if self.path.exists() else {}
        )

    def transact(self, action):
        # Validation and all changes happen on private state. In particular, an
        # exception from the action must not alter the next in-memory retry.
        candidate = copy.deepcopy(self.data)
        result = copy.deepcopy(action(candidate))
        if candidate == self.data:
            return result

        # Do all potentially failing preparation before publishing either copy.
        payload = json.dumps(candidate, separators=(',', ':'))
        missing_parents = []
        for parent in (self.path.parent, *self.path.parent.parents):
            if parent.exists():
                break
            missing_parents.append(parent)
        created_parents = []
        temp_path = None
        try:
            for parent in reversed(missing_parents):
                parent.mkdir()
                created_parents.append(parent)
            with tempfile.NamedTemporaryFile(
                mode='w', encoding='utf-8', dir=self.path.parent,
                prefix='.exports-', suffix='.tmp', delete=False,
            ) as temp:
                temp_path = Path(temp.name)
                temp.write(payload)
                temp.flush()
                os.fsync(temp.fileno())
            # Same-directory replacement is atomic. Nothing fallible remains
            # after this publication point (no process kill within a method).
            os.replace(temp_path, self.path)
        except BaseException:
            # Remove only files/directories created by this transaction. Keep
            # the original exception if the filesystem also rejects cleanup.
            if temp_path is not None:
                try:
                    temp_path.unlink(missing_ok=True)
                except OSError:
                    pass
            for parent in reversed(created_parents):
                try:
                    parent.rmdir()
                except OSError:
                    pass
            raise
        self.data = candidate
        return result


def identifier(value):
    if not isinstance(value, str) or not value or len(value) > 128:
        raise ValueError('invalid identifier')
    return value


def integer(value, low=0, high=1_000_000_000):
    if type(value) is not int or not low <= value <= high:
        raise ValueError('invalid integer')
    return value

