from .store import identifier, integer

def rows_value(rows, *, nonempty=False):
    if not isinstance(rows, list) or len(rows) > 1000 or (nonempty and not rows):
        raise ValueError('rows')
    seen = set()
    for row in rows:
        if not isinstance(row, dict) or set(row) != {'id', 'value'}: raise ValueError('row shape')
        identifier(row['id'])
        if not isinstance(row['value'], str) or len(row['value']) > 10000: raise ValueError('row value')
        if row['id'] in seen: raise ValueError('duplicate row')
        seen.add(row['id'])
    return rows

def live(job, token, now):
    identifier(token); integer(now)
    if (job['state'] != 'running' or job['lease']['token'] != token
            or now >= job['lease']['expires']):
        raise ValueError('lease not live')

